const store = {
  value: 0,
  listeners: new Set(),

  getSnapshot() {
    return this.value;
  },

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  },

  increment() {
    this.value += 1;
    this.listeners.forEach(listener => listener());
  }
};

function Counter() {
